def foldl(function, list, initial):
    acc = initial
    for item in list:
        acc = function(acc, item)
    return acc


def foldr(function, list, initial):
    acc = initial
    for index in range(len(list) - 1, -1, -1):
        acc = function(list[index], acc)
    return acc

